(function() {
  var _result = {};
  try {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
      _result = {status:"error", message:"No active comp"};
      return JSON.stringify(_result);
    }
    var p = {
      layerName: ${layerName},
      ringCount: ${ringCount},
      ringSpeed: ${ringSpeed},
      ringColor: ${ringColor},
      ringWidth: ${ringWidth},
      fadeDistance: ${fadeDistance}
    };
    var layer = p.layerName ? comp.layers.byName(p.layerName) : comp.layer(1);
    if (!layer) {
      _result = {status:"error", message:"Layer not found"};
      return JSON.stringify(_result);
    }
    var circle = comp.layers.addShape();
    circle.name = "Energy Rings";
    var grp = circle.property("Contents").addProperty("ADBE Group");
    var ellipse = grp.property("Contents").addProperty("ADBE Ellipse");
    ellipse.property("ADBE Ellipse-0001").setValue([comp.width / 2, comp.height / 2]);
    ellipse.property("ADBE Ellipse-0002").setValue([p.fadeDistance, p.fadeDistance]);
    var stroke = grp.property("Contents").addProperty("ADBE Stroke");
    stroke.property("ADBE Stroke-0001").setValue(p.ringColor);
    stroke.property("ADBE Stroke-0002").setValue(p.ringWidth);
    stroke.property("ADBE Stroke-0003").setValue(100);
    var trim = grp.property("Contents").addProperty("ADBE Trim Paths");
    trim.property("ADBE Trim Paths-0001").setValueAtTime(comp.time, 0);
    trim.property("ADBE Trim Paths-0001").setValueAtTime(comp.time + p.duration, 100);
    trim.property("ADBE Trim Paths-0002").setValueAtTime(comp.time, 100);
    trim.property("ADBE Trim Paths-0002").setValueAtTime(comp.time + p.duration, 100);
    _result = {status:"success", message:"能量环特效已创建"};
  } catch(e) {
    _result = {status:"error", message:"Error: " + e.toString()};
  }
  return JSON.stringify(_result);
})();

(function() {
  var _result = {};
  try {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
      _result = {status:"error", message:"No active comp"};
      return JSON.stringify(_result);
    }
    var p = {
      layerName: ${layerName},
      duration: ${duration},
      sweepDirection: ${sweepDirection},
      beamWidth: ${beamWidth},
      beamColor: ${beamColor},
      edgeSoftness: ${edgeSoftness}
    };
    var adjustmentLayer = comp.layers.addAdjustmentLayer();
    adjustmentLayer.name = "Light Sweep";
    adjustmentLayer.inPoint = comp.time;
    adjustmentLayer.outPoint = comp.time + p.duration;
    var gradient = adjustmentLayer.Effects.addProperty("ADBE Ramp");
    gradient.property("ADBE Ramp-0001").setValue("Linear Ramp");
    gradient.property("ADBE Ramp-0002").setValue(p.beamColor);
    gradient.property("ADBE Ramp-0003").setValue([0, 0, 0]);
    gradient.property("ADBE Ramp-0004").setValueAtTime(comp.time, p.sweepDirection === "left" ? [-p.beamWidth, comp.height / 2] : [comp.width + p.beamWidth, comp.height / 2]);
    gradient.property("ADBE Ramp-0004").setValueAtTime(comp.time + p.duration, p.sweepDirection === "left" ? [comp.width + p.beamWidth, comp.height / 2] : [-p.beamWidth, comp.height / 2]);
    gradient.property("ADBE Ramp-0006").setValue(p.beamWidth);
    _result = {status:"success", message:"光扫特效已创建"};
  } catch(e) {
    _result = {status:"error", message:"Error: " + e.toString()};
  }
  return JSON.stringify(_result);
})();

(function() {
