(function() {
  var _result = {};
  try {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
      _result = {status:"error", message:"No active comp"};
      return JSON.stringify(_result);
    }
    var p = {
      layerName: ${layerName},
      lineCount: ${lineCount},
      lineOpacity: ${lineOpacity},
      lineColor: ${lineColor},
      flickerRate: ${flickerRate}
    };
    var adjustmentLayer = comp.layers.addAdjustmentLayer();
    adjustmentLayer.name = "Scanline Effect";
    var pattern = adjustmentLayer.Effects.addProperty("ADBE Grid");
    pattern.property("ADBE Grid-0001").setValue([comp.width, comp.height / p.lineCount]);
    pattern.property("ADBE Grid-0002").setValue([0, 0]);
    pattern.property("ADBE Grid-0003").setValue(p.lineColor);
    pattern.property("ADBE Grid-0005").setValue([1, 0, 0]);
    pattern.property("ADBE Grid-0006").setValue(0);
    adjustmentLayer.opacity.setValue(p.lineOpacity);
    if (p.flickerRate > 0) {
      adjustmentLayer.opacity.expression = "wiggle(${flickerRate}, 5)";
    }
    _result = {status:"success", message:"扫描线特效已创建"};
  } catch(e) {
    _result = {status:"error", message:"Error: " + e.toString()};
  }
  return JSON.stringify(_result);
})();

